#include "abc/core.hpp"
#include "../src/binary_codec.hpp"
#include <algorithm>
#include <bit>
#include <fstream>
#include <iostream>
#include <sstream>
namespace {
unsigned checks=0,failures=0;
void check(bool ok,std::string_view s){++checks;if(!ok){++failures;if(failures<20)std::cerr<<"FAIL "<<s<<'\n';}}
struct Memory:abc::BinaryDevice{std::string data;std::size_t cursor=0;std::int64_t position(abc::SourceLocation)const override{return static_cast<std::int64_t>(cursor);}void seek(std::int64_t n,abc::SourceLocation)override{cursor=static_cast<std::size_t>(n);}std::size_t read(std::span<char> out,abc::SourceLocation)override{const auto n=std::min(out.size(),cursor<data.size()?data.size()-cursor:0);if(n)std::copy_n(data.data()+cursor,n,out.data());cursor+=n;return n;}void write(std::string_view in,abc::SourceLocation)override{if(cursor+in.size()>data.size())data.resize(cursor+in.size());std::copy(in.begin(),in.end(),data.begin()+static_cast<std::ptrdiff_t>(cursor));cursor+=in.size();}};
std::vector<std::string> split(std::string_view s){std::vector<std::string> r;std::size_t a=0;for(;;){const auto b=s.find('\t',a);r.emplace_back(s.substr(a,b==s.npos?b:b-a));if(b==s.npos)return r;a=b+1;}}
std::string unhex(std::string_view s){std::string r;if(s!="-")for(std::size_t n=0;n<s.size();n+=2)r+=static_cast<char>(std::stoul(std::string(s.substr(n,2)),nullptr,16));return r;}
std::string hex(std::string_view s){if(s.empty())return "-";std::string r;for(unsigned char c:s){r+="0123456789abcdef"[c>>4];r+="0123456789abcdef"[c&15];}return r;}
std::u16string units(std::string_view s){std::u16string r;if(s!="-")for(std::size_t n=0;n<s.size();n+=4)r+=static_cast<char16_t>(std::stoul(std::string(s.substr(n,4)),nullptr,16));return r;}
std::string units_hex(std::u16string_view s){if(s.empty())return "-";std::string r;for(char16_t c:s)for(int n=12;n>=0;n-=4)r+="0123456789abcdef"[(c>>n)&15];return r;}
abc::Type type(std::string_view n){if(n=="bool")return abc::Type::boolean;if(n=="sbyte")return abc::Type::shortint;auto t=abc::find_type(n);if(!t)throw std::runtime_error("Unknown wire scalar");return *t;}
abc::Value value(abc::Type t,const std::string& s){using T=abc::Type;if(t==T::character)return units(s).at(0);if(t==T::string)return units(s);const auto raw=unhex(s);std::uint64_t bits=0;for(unsigned n=0;n<raw.size();++n)bits|=static_cast<std::uint64_t>(static_cast<std::uint8_t>(raw[n]))<<(n*8);switch(t){case T::boolean:return bits!=0;case T::byte:return static_cast<std::uint8_t>(bits);case T::shortint:return std::bit_cast<std::int8_t>(static_cast<std::uint8_t>(bits));case T::word:return static_cast<std::uint16_t>(bits);case T::smallint:return std::bit_cast<std::int16_t>(static_cast<std::uint16_t>(bits));case T::integer:return std::bit_cast<std::int32_t>(static_cast<std::uint32_t>(bits));case T::longword:return static_cast<std::uint32_t>(bits);case T::int64:return std::bit_cast<std::int64_t>(bits);case T::uint64:return bits;case T::single:return std::bit_cast<float>(static_cast<std::uint32_t>(bits));case T::real:return std::bit_cast<double>(bits);default:throw std::runtime_error("Wire value type");}}
std::string encoded(abc::Type t,const abc::Value& v){using T=abc::Type;if(t==T::character)return units_hex(std::u16string(1,std::get<char16_t>(v)));if(t==T::string)return units_hex(std::get<std::u16string>(v));std::uint64_t bits=0;unsigned width=0;switch(t){case T::boolean:bits=std::get<bool>(v)?1:0;width=1;break;case T::byte:bits=std::get<std::uint8_t>(v);width=1;break;case T::shortint:bits=static_cast<std::uint8_t>(std::get<std::int8_t>(v));width=1;break;case T::word:bits=std::get<std::uint16_t>(v);width=2;break;case T::smallint:bits=static_cast<std::uint16_t>(std::get<std::int16_t>(v));width=2;break;case T::integer:bits=static_cast<std::uint32_t>(std::get<std::int32_t>(v));width=4;break;case T::longword:bits=std::get<std::uint32_t>(v);width=4;break;case T::int64:bits=static_cast<std::uint64_t>(std::get<std::int64_t>(v));width=8;break;case T::uint64:bits=std::get<std::uint64_t>(v);width=8;break;case T::single:bits=std::bit_cast<std::uint32_t>(std::get<float>(v));width=4;break;case T::real:bits=std::bit_cast<std::uint64_t>(std::get<double>(v));width=8;break;default:throw std::runtime_error("Wire encoding type");}std::string bytes;for(unsigned n=0;n<width;++n)bytes+=static_cast<char>(bits>>(n*8));return hex(bytes);}
void reference(const std::filesystem::path& path){std::ifstream file(path);check(bool(file),"Actual binary codec reference");Memory memory;std::unique_ptr<abc::BinaryCodec> codec;std::string line;unsigned rows=0;while(std::getline(file,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();if(line.empty()||line[0]=='#')continue;const auto f=split(line);if(f.size()!=8)throw std::runtime_error("Wire reference width");const auto& op=f[2];std::string error="ok",output="-";try{if(op=="writer"||op=="reader"){memory.data=unhex(f[4]);memory.cursor=0;codec=std::make_unique<abc::BinaryCodec>(memory,abc::TextEncoding{static_cast<abc::TextEncodingKind>(std::stoul(f[1])),false,false});}else if(op=="seek")memory.seek(std::stoll(f[4]),{});else if(op=="write"){memory.data.clear();memory.cursor=0;const auto t=type(f[3]);codec->write(t,value(t,f[4]),{0,53,2},{});output=hex(memory.data);}else if(op=="read")output=encoded(type(f[3]),codec->read(type(f[3]),{0,53,2},{}));else throw std::runtime_error("Unknown wire operation");}catch(const abc::Error& e){error=e.code;if(op=="write")output=hex(memory.data);check(!e.russian.empty()&&*e.what()&&e.location.line==53,"Bilingual codec exception");}auto expected=f[5];if(expected=="ArgumentException")expected="E_ARGUMENT";else if(expected=="EndOfStreamException")expected="E_EOF";else if(expected=="IOException")expected="E_IO";else if(expected=="FormatException")expected="E_FORMAT";check(error==expected&&output==f[6]&&memory.position({})==std::stoll(f[7]),"Wire row "+std::to_string(rows)+" cp="+f[1]+" "+op+" "+f[3]+" actual="+error+"/"+output+"/"+std::to_string(memory.position({}))+" expected="+expected+"/"+f[6]+"/"+f[7]);++rows;}check(rows==410752,"All actual binary codec traces consumed");}
}
int main(int argc,char** argv){try{if(argc!=2)throw std::runtime_error("Pass unpacked binary codec reference");reference(std::filesystem::path(argv[1]));}catch(const std::exception& e){check(false,e.what());}std::cout<<checks<<" binary codec checks, "<<failures<<" failures\n";return failures?1:0;}